function Login({ onAuthenticated }: { onAuthenticated: (user: AuthUser, csrf: string) => void }) { const [identifier, setIdentifier] = useState(""); const [password, setPassword] = useState(""); const [remember, setRemember] = useState(true); const [showPassword, setShowPassword] = useState(false); const [challenge, setChallenge] = useState(""); const [otp, setOtp] = useState(""); const [forgotMode, setForgotMode] = useState(false); const [loading, setLoading] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState(""); async function submit(event: FormEvent) { event.preventDefault(); setError(""); setMessage(""); setLoading(true); try { if (forgotMode) { const r = await apiRequest<{ message: string }>("/auth/forgot-password.php", { method: "POST", body: JSON.stringify({ email: identifier }) }); if (r.error) throw new Error(r.error); setMessage(r.data?.message || "Check your email for a reset link."); return; } if (challenge) { const r = await apiRequest<{ user: AuthUser; csrf_token: string }>("/auth/verify-otp.php", { method: "POST", body: JSON.stringify({ challenge, code: otp, remember }) }); if (r.error || !r.data) throw new Error(r.error || "Unable to verify code."); onAuthenticated(r.data.user, r.data.csrf_token); return; } const r = await apiRequest<{ otp_required?: boolean; challenge?: string; message?: string; user?: AuthUser; csrf_token?: string }>("/auth/login.php", { method: "POST", body: JSON.stringify({ identifier, password, remember }) }); if (r.error || !r.data) throw new Error(r.error || "Unable to sign in."); if (r.data.otp_required && r.data.challenge) { setChallenge(r.data.challenge); setMessage(r.data.message || "Enter the code sent to your email."); return; } if (r.data.user && r.data.csrf_token) onAuthenticated(r.data.user, r.data.csrf_token); } catch (err) { setError(err instanceof Error ? err.message : "Unable to sign in."); } finally { setLoading(false); } } return <main className="login-page"><section className="login-brand"><div className="login-brand-inner"><img src="/logo.png" alt="JUVA Oil Services Nigeria Limited" /><p className="eyebrow">CERTIFY MANAGER</p><h1>Inspection integrity, from field evidence to verified certificate.</h1><p>One controlled system for equipment records, inspection workflows, approvals, certificate issuance and public verification.</p><div className="login-assurance"><ShieldCheck size={20} /><span><strong>Verification-first security</strong>Every issued certificate is traceable, status-controlled and audit logged.</span></div></div></section><section className="login-form-wrap"><form className="login-form" onSubmit={submit}><div className="login-heading"><span className="login-mark"><LockKeyhole size={20} /></span><div><p>SECURE STAFF ACCESS</p><h2>{forgotMode ? "Reset password" : challenge ? "Verify login" : "Sign in to continue"}</h2></div></div>{error && <div className="form-alert form-error">{error}</div>}{message && <div className="form-alert form-success">{message}</div>}{!challenge && <label>Email or username<input value={identifier} onChange={(e) => setIdentifier(e.target.value)} autoComplete="username" /></label>}{!forgotMode && !challenge && <label>Password<div className="password-field"><input type={showPassword ? "text" : "password"} value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="current-password" /><button type="button" onClick={() => setShowPassword((v) => !v)}>{showPassword ? "Hide" : "Show"}</button></div></label>}{challenge && <label>Email verification code<input value={otp} onChange={(e) => setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))} inputMode="numeric" autoComplete="one-time-code" /></label>}{!forgotMode && <div className="login-options"><label className="check-label"><input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} /> Remember this device</label><button type="button" className="link-button" onClick={() => setForgotMode(true)}>Forgot password?</button></div>}{forgotMode && <button type="button" className="link-button back-link" onClick={() => setForgotMode(false)}>Back to sign in</button>}<button className="login-button" disabled={loading}>{loading ? "Please wait..." : forgotMode ? "Send reset link" : challenge ? "Verify code" : "Sign in securely"} <ArrowRight size={17} /></button><p className="login-help">Access is restricted to authorised JUVA personnel and client users.</p></form><footer>JUVA Oil Services Nigeria Limited<br />52 Rumuolumeni Road, Port Harcourt</footer></section></main>; }
function ResetPassword({ token }: { token: string }) { const [password, setPassword] = useState(""); const [message, setMessage] = useState(""); const [error, setError] = useState(""); async function submit(e: FormEvent) { e.preventDefault(); const r = await apiRequest<{ message: string }>("/auth/reset-password.php", { method: "POST", body: JSON.stringify({ token, password }) }); if (r.error) setError(r.error); else setMessage(r.data?.message || "Password updated."); } return <main className="login-page"><section className="login-brand"><div className="login-brand-inner"><img src="/logo.png" alt="JUVA Oil" /><p className="eyebrow">ACCOUNT SETUP</p><h1>Set a secure password for Certify Manager.</h1><p>Invitation and reset links are single-use and expire automatically.</p></div></section><section className="login-form-wrap"><form className="login-form" onSubmit={submit}><div className="login-heading"><span className="login-mark"><ShieldCheck size={20} /></span><div><p>SECURE SETUP</p><h2>Create password</h2></div></div>{error && <div className="form-alert form-error">{error}</div>}{message && <div className="form-alert form-success">{message}</div>}<label>New password<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} /></label><button className="login-button">Save password <ArrowRight size={17} /></button></form></section></main>; }
